#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-replay-exchanges-without-the-server. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
cat > site/report.csv <<'EOF'
region,total
north,12
south,7
EOF
cat > record.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Starts surl on port $1, records each name below into rec/ (the response head in
# <name>.head, the body in <name>), then stops the server. Usage: sh record.sh <port>
url="http://127.0.0.1:$1"
surl -s --directory site "$url/" > /dev/null 2>&1 &
pid=$!
tries=0
until curl -s -o /dev/null --max-time 2 "$url/"; do      # wait until it answers, 10 s at most
  tries=$((tries + 1)); [ "$tries" -ge 50 ] && { kill "$pid"; exit 1; }
  sleep 0.2
done
mkdir -p rec
for name in hello.txt report.csv missing.txt; do
  curl -s --max-time 10 -D "rec/$name.head" -o "rec/$name" "$url/$name"
  echo "recorded $name: $(head -n 1 "rec/$name.head" | tr -d '\r')"
done
kill "$pid"; wait "$pid" 2> /dev/null
curl -s -o /dev/null --max-time 5 "$url/hello.txt"
echo "server stopped: curl exit $?"
EOF
cat > replay.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Fetches the recorded body of $1 with curl from a file: URL, so no server is needed.
# Usage: sh replay.sh <name>
dir=$(cd rec && { pwd -W 2> /dev/null || pwd; })   # pwd -W: the Windows path, in Git Bash
case $dir in /*) base="file://$dir" ;; *) base="file:///$dir" ;; esac
curl -sS --max-time 10 "$(printf '%s/%s' "$base" "$1" | sed 's/ /%20/g')"
EOF
sh record.sh 8080 && sh replay.sh hello.txt
